exif_data_load_data_content (ExifData *data, ExifIfd ifd,
                             const unsigned char *d,
                             unsigned int ds, unsigned int offset, unsigned int recursion_cost)
{
        ExifLong o, thumbnail_offset = 0, thumbnail_length = 0;
        ExifShort n;
        ExifEntry *entry;
        unsigned int i;
        ExifTag tag;

        if (!data || !data->priv)
                return;

        /* check for valid ExifIfd enum range */
        if ((((int)ifd) < 0) || ( ((int)ifd) >= EXIF_IFD_COUNT))
          return;

        if (recursion_cost > 170) {
                /*
                 * recursion_cost is a logarithmic-scale indicator of how expensive this
                 * recursive call might end up being. It is an indicator of the depth of
                 * recursion as well as the potential for worst-case future recursive
                 * calls. Since it's difficult to tell ahead of time how often recursion
                 * will occur, this assumes the worst by assuming every tag could end up
                 * causing recursion.
                 * The value of 170 was chosen to limit typical EXIF structures to a
                 * recursive depth of about 6, but pathological ones (those with very
                 * many tags) to only 2.
                 */
                exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA, "ExifData",
                          "Deep/expensive recursion detected!");
                return;
        }

        /* Read the number of entries */
        if (CHECKOVERFLOW(offset, ds, 2)) {
                exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA, "ExifData",
                          "Tag data past end of buffer (%u+2 > %u)", offset, ds);
                return;
        }
        n = exif_get_short (d + offset, data->priv->order);
        exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
                  "Loading %hu entries...", n);
        offset += 2;

        /* Check if we have enough data. */
        if (CHECKOVERFLOW(offset, ds, 12*n)) {
                n = (ds - offset) / 12;
                exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
                                  "Short data; only loading %hu entries...", n);
        }

        for (i = 0; i < n; i++) {

                tag = exif_get_short (d + offset + 12 * i, data->priv->order);
                switch (tag) {
                case EXIF_TAG_EXIF_IFD_POINTER:
                case EXIF_TAG_GPS_INFO_IFD_POINTER:
                case EXIF_TAG_INTEROPERABILITY_IFD_POINTER:
                case EXIF_TAG_JPEG_INTERCHANGE_FORMAT_LENGTH:
                case EXIF_TAG_JPEG_INTERCHANGE_FORMAT:
                        o = exif_get_long (d + offset + 12 * i + 8,
                                           data->priv->order);
                        if (o >= ds) {
                                exif_log (data->priv->log, EXIF_LOG_CODE_CORRUPT_DATA, "ExifData",
                                          "Tag data past end of buffer (%u > %u)", offset+2, ds);
                                return;
                        }
                        /* FIXME: IFD_POINTER tags aren't marked as being in a
                         * specific IFD, so exif_tag_get_name_in_ifd won't work
                         */
                        exif_log (data->priv->log, EXIF_LOG_CODE_DEBUG, "ExifData",
                                  "Sub-IFD entry 0x%x ('%s') at %u.", tag,
                                  exif_tag_get_name(tag), o);
                        switch (tag) {
                        case EXIF_TAG_EXIF_IFD_POINTER:
                                CHECK_REC (EXIF_IFD_EXIF);
                                exif_data_load_data_content (data, EXIF_IFD_EXIF, d, ds, o,
                                        recursion_cost + level_cost(n));
                                break;
